INSERT INTO blog_worker.research_reference(id,definition)
SELECT id,definition FROM jsonb_to_recordset($references$[{"id":"ARTICLE_PRIMARY_GOOGLE_BLOG","definition":{"reference_id":"PRIMARY_GOOGLE_BLOG","enabled":true,"content_approved":true,"url":"https://blog.google/","article_hosts":["blog.google","www.blog.google"],"rights_reference":"Excerto de página pública para apuração e atribuição; sem reprodução integral, acesso restrito ou licença de imagens; respeitar robots.txt"}},{"id":"ARTICLE_PRIMARY_MICROSOFT_BLOG","definition":{"reference_id":"PRIMARY_MICROSOFT_BLOG","enabled":true,"content_approved":true,"url":"https://blogs.microsoft.com/","article_hosts":["blogs.microsoft.com","www.blogs.microsoft.com"],"rights_reference":"Excerto de página pública para apuração e atribuição; sem reprodução integral, acesso restrito ou licença de imagens; respeitar robots.txt"}},{"id":"ARTICLE_PRIMARY_META_NEWS","definition":{"reference_id":"PRIMARY_META_NEWS","enabled":true,"content_approved":true,"url":"https://about.fb.com/news/","article_hosts":["about.fb.com","www.about.fb.com"],"rights_reference":"Excerto de página pública para apuração e atribuição; sem reprodução integral, acesso restrito ou licença de imagens; respeitar robots.txt"}}]$references$::jsonb) AS x(id text,definition jsonb);
